package main

import "fmt"

type courseStage struct {
	title   string
	lessons []int
}

var courseStages = []courseStage{
	{"First hands", []int{0, 1, 2, 9, 10, 11, 12}},
	{"Hand shape", []int{3, 4, 13, 14, 15, 16, 17}},
	{"Yaku and value", []int{5, 6, 18, 19, 20, 21, 7}},
	{"Table decisions", []int{22, 23, 8, 24, 25, 26, 27}},
}

type workedExample struct{ title, hand, why string }
type checkQuestion struct {
	prompt  string
	choices []string
	correct int
	why     string
}

func init() {
	lessons = append(lessons,
		lesson{"Winds and the dealer", "Beginner introduction; Book I §3.2", "Your seat wind identifies your place at the table. East is the dealer; turns run East, South, West, North. The round wind is shared by everyone. A set of your seat wind or the round wind earns yakuhai. A pair does not. A wind that is both seat and round wind earns two han as a set.", "111z222z33z", "You sit South in an East round. Which wind sets are valuable?", []string{"East and South", "Only South", "All four winds"}, 0, "East is the round wind and South is your seat wind. Both sets earn one han."},
		lesson{"Chi, pon and open hands", "Beginner introduction; Book I Chapter 9", "Chi completes a run using a discard from the player on your left. Pon completes a set using any opponent's discard. Both expose a group and open the hand. You then discard without taking a normal draw. Opening removes riichi and menzen-tsumo eligibility, so identify your open-hand yaku before calling.", "34m77z", "You hold 3–4 characters. Who can supply 2 characters for chi?", []string{"Any opponent", "Only the player on your left", "Only the dealer"}, 1, "Chi is restricted to the left player. Pon can take a tile from any opponent."},
		lesson{"Furiten and passing ron", "Book I Chapters 7–8", "If any tile completing your current wait is in your own discards, you cannot ron on any tile in that wait. This is discard furiten. You may still win by tsumo. Passing a legal ron normally blocks ron until your next draw; after riichi, passing a win blocks ron for the rest of that hand. Furiten is a restriction on ron, not a penalty for drawing your own winning tile.", "123m456p23467s55p", "You wait on 5 or 8 bamboo and previously discarded 5 bamboo. Can you ron on 8 bamboo?", []string{"Yes, only 5 is blocked", "No, the entire wait is furiten", "Only from the dealer"}, 1, "The discarded 5 makes the whole current wait furiten. Tsumo on either winning tile is still possible."},
		lesson{"The wall, draws and kans", "Beginner introduction; Book I §9.3", "A normal four-player game uses a live wall and a 14-tile dead wall. The live wall initially has 70 draws after the deal, including the dealer's first extra tile. A kan is four identical tiles treated as one group: it requires a replacement draw and affects dora. A closed kan normally keeps the hand closed. Do not call kan just because you can; it also gives opponents more potential dora.", "5555p", "Does a concealed kan automatically open your hand?", []string{"Yes", "No", "Only if it uses a terminal"}, 1, "A concealed kan normally preserves closed-hand status. Riichi-kan legality has additional wait-preservation restrictions."},
		lesson{"Read your shanten", "Book I §3.2", "Shanten counts the tile exchanges needed to reach tenpai. Zero is tenpai; one means one exchange from tenpai; minus one is a complete shape. Calculate the best shape among a standard hand, seven pairs and thirteen orphans. A low shanten does not guarantee a yaku or a safe discard.", "123m456p23467s55p", "What does shanten 0 mean?", []string{"A complete hand", "Tenpai", "No legal yaku"}, 1, "Shanten 0 is tenpai. A complete shape is shanten −1, and yaku are a separate check."},
		lesson{"Count useful draws", "Book I Chapters 3–4", "Ukeire counts tiles that improve your shanten. Prefer a discard that preserves more useful draws when shanten is tied, unless hand value or defense justifies another choice. Subtract copies you hold and copies visible on the table. Counting tile types alone can hide a large difference in the number of available copies.", "45m46p", "Before visible tiles are subtracted, which shape has more ways to complete a run?", []string{"4–5 characters", "4–6 dots", "They are equal"}, 0, "4–5 accepts 3 or 6: up to eight copies. 4–6 accepts only 5: up to four."},
		lesson{"Choose your pair", "Book I §3.2.6", "A standard hand needs exactly one final pair. Two pairs can be flexible: one may become a set while the other remains the head. A third pair may force you to break a stronger run shape. Four or more pairs can also make seven pairs worth comparing. These are shape guidelines, not instructions to break every third pair automatically.", "22m55p78s", "Why can two pairs be useful in a standard hand?", []string{"They count as two complete groups", "Either can become a set while the other stays the head", "They always supply a yaku"}, 1, "One pair can become a set without leaving you without a head. Pairs themselves are not complete groups."},
		lesson{"See all your waits", "Book I §§3.3–3.4", "A hand can have more than one decomposition. In 2–3–4–5, either 2 or 5 can be the pair while the other three tiles form a run. In 3–4–5–6–7, adding 2, 5 or 8 makes two runs. Check every legal decomposition instead of fixing one grouping too early. Complex waits still need a yaku.", "2345m", "If all other groups are complete, which tiles finish the 2–3–4–5 characters block as a run and a pair?", []string{"Only 2", "2 or 5", "1 or 6"}, 1, "With 2, use 22 + 345. With 5, use 234 + 55. This is a stretched single wait, not pinfu's two-sided wait."},
		lesson{"Find the redundant tile", "Book I Chapter 4", "Separate the hand into five candidate blocks. A block can contain overlapping incomplete groups, so a tile may look connected but add no useful draw. Keep enough support in the weakest block. Efficiency suggestions ignore defense; a technically efficient discard may still be too dangerous against riichi.", "5578m2455p133s777z", "In the 2–4–5–5 dots block, if it only needs to become one group, what is redundant?", []string{"2 dots", "Both 5 dots", "4 dots"}, 0, "The 45 shape already accepts 3 dots. Keeping the extra 2 does not add that acceptance; 55 also preserves the set option."},
		lesson{"Pinfu without shortcuts", "Book I §5.3", "Pinfu is one han and needs four runs, a closed hand, a non-value pair and a two-sided winning wait. A dragon pair, seat-wind pair or round-wind pair prevents it. Terminal tiles are allowed. Do not confuse 'all runs' with pinfu: the pair and exact winning tile matter too.", "123m456p234678s55p", "For this closed hand, won on 8 bamboo, can the pair of 5 dots qualify for pinfu?", []string{"Yes", "No, pairs must be honors", "No, terminal runs are forbidden"}, 0, "5 dots is a non-value pair and 8 bamboo completes the two-sided 67 wait. All four groups are runs."},
		lesson{"Value sets and open yaku", "Book I §3.2; Chapter 5", "A set of White, Green or Red dragons earns one han. A set of the round or seat wind also earns one han for each role it fills. These yaku survive opening. Tanyao also survives opening under the rules used here, but every tile must be a number from 2 to 8. A pair of dragons is not yakuhai.", "123m456p789s777z55p", "An open hand has a set of Red dragons. Does that set provide a yaku?", []string{"Yes, one han", "Only with riichi", "No, dragons must be the pair"}, 0, "A dragon set is yakuhai, open or closed. An open hand cannot declare riichi."},
		lesson{"Dora and red fives", "Book I §3.2; Chapter 6", "A dora indicator points to the next tile, not to itself. Number suits wrap 9 to 1. Winds cycle East, South, West, North; dragons cycle White, Green, Red. Red fives are still rank five and also count as bonus dora. Dora never replaces the required yaku. The current scoring lab omits red fives.", "9m4p7z", "With a 9 characters indicator, which tile is dora?", []string{"9 characters", "1 characters", "Red dragon"}, 1, "Number indicators wrap from 9 to 1 within the same suit."},
		lesson{"Alternative yaku routes", "Book I §§5.1–5.5", "Seven pairs uses seven distinct pairs, stays closed and has exactly 25 fu. A quad cannot count as two pairs. Honitsu uses one numbered suit plus honors: three han closed or two open. Sanshoku uses the same run in all three suits, and ittsu uses 123, 456 and 789 in one suit; both are two han closed or one open. Avoid forcing an expensive route when it makes the hand much slower.", "1122m3344p5566s77z", "Can four identical tiles count as two pairs for seven pairs?", []string{"Yes", "No", "Only when they are dragons"}, 1, "Seven pairs needs seven distinct tile types. A quad is only one type."},
		lesson{"Fu you can rely on", "Book I Chapter 6", "Seven pairs is always 25 fu. Pinfu tsumo is 20 fu; pinfu ron is 30 fu. Otherwise start at 20, add the relevant contributions and round up to the next ten. Closed ron adds 10; self-draw normally adds 2. Sets, kans, value pairs and difficult waits can add fu. Do not treat the book's 'almost always' shortcuts as exact rules.", "123m456p234678s55p", "How much fu is a closed pinfu hand worth on ron?", []string{"20 fu", "25 fu", "30 fu"}, 2, "Pinfu ron uses 20 base fu plus 10 for closed ron: 30 fu. Pinfu tsumo is the special 20-fu case."},
		lesson{"Riichi or stay quiet?", "Book I Chapter 7", "Riichi adds a yaku and potential bonuses, but locks the hand and costs a 1,000-point deposit. An early good-wait closed tenpai often makes a good riichi candidate. Staying quiet (dama) can be useful when a legal hand is already valuable, when a small win meets your placement goal, or when you need flexibility. A complete shape with no yaku cannot ron just because you chose dama.", "123m456p23467s55p", "Early in the hand, with a closed good-wait tenpai and no threat, which is a reasonable default?", []string{"Consider declaring riichi", "Always wait for a single-tile wait", "Open the hand first"}, 0, "Good waits and early turns favor attacking with riichi. Score, existing yaku and table threats can change the decision."},
		lesson{"Suji is not a guarantee", "Book I §8.2", "Genbutsu is safe from one opponent's ron because of furiten. Suji is weaker evidence: a discarded 4 can rule out that player's 1–4 and 4–7 two-sided waits, but not a 1 or 7 used in a pair or set wait. Suji does not prove a tile safe. A 1–4–7 line is not a magic shield, and safety against one player says nothing certain about the other two.", "147p", "An opponent discarded 4 dots. Is 1 dots guaranteed safe from their ron?", []string{"Yes", "No, other wait types remain", "Only if they declared riichi"}, 1, "They can still have a pair or set wait involving 1 dots. Suji mainly addresses specific two-sided waits."},
		lesson{"Call with a plan", "Book I Chapter 9", "Before chi or pon, name your open-hand yaku, the discard that follows, and what the call improves. A fast yakuhai hand or a clear tanyao route may justify opening. A cheap, distant hand often gains little and loses defensive flexibility. Calling can reduce the value of sanshoku, ittsu and honitsu. Kan adds still more risk through extra dora and a replacement draw.", "234m56p234s777z55p", "What should you know before calling pon?", []string{"Only that three identical tiles look useful", "Your yaku route and the discard after the call", "That riichi will still be available"}, 1, "Plan the yaku and follow-up discard before taking the tile. Opening usually removes riichi."},
		lesson{"Push or fold", "Book I Chapter 8", "Compare your hand's readiness, value and wait with the threat. A cheap two-shanten hand late against riichi usually favors folding with genbutsu. A valuable tenpai may justify pushing, but it still carries risk. Reassess every turn. Folding means selecting safer discards to avoid dealing in; it does not mean discarding blindly or abandoning awareness of the other players.", "1239m4567p2466s1z", "Late in the hand, you are two-shanten with little value and an opponent declares riichi. What is a sensible default?", []string{"Push any useful tile", "Fold using their genbutsu when possible", "Call kan to catch up"}, 1, "The chance of finishing a cheap distant hand is low, while dealing in may be costly. Safety usually matters more here."},
		lesson{"Finish a real match", "Book I Chapter 10; beginner review", "A match is about your final score and placement, not winning every hand. Track who is dealer, the round, points, honba and riichi deposits. Each honba adds 300 to ron or 100 from each opponent on tsumo. A drawn hand may involve tenpai payments and dealer continuation, depending on the situation. Near the end, calculate whether a small win is enough before taking unnecessary risks.", "123m456p234678s55p", "In the final hand, a small legal win secures the placement you need. Must you chase a bigger yaku?", []string{"Yes, always maximize han", "No, the placement goal can favor taking the win", "Only dealer wins count"}, 1, "The target is the match result. A sufficient small win can be better than a risky attempt at extra value."},
	)
}

var workedHands = map[int][2]workedExample{
	0:  {{"Three number suits", "123m123p123s", "Each suit has ranks 1–9, with four copies of every type. Matching ranks across suits do not form a run."}, {"Honors are separate", "1234567z", "East, South, West, North, White, Green and Red are seven distinct honor types. They never form runs."}},
	1:  {{"Four groups and a head", "123m456p789s777z55p", "The runs 123m, 456p and 789s plus the Red-dragon set are four groups. 55p is the head; Red dragons supply a yaku."}, {"Honors are not consecutive", "123z", "East–South–West is not a group. To make an honor set, collect three identical honors instead."}},
	2:  {{"Before a draw", "123m456p23467s55p", "This is 13 tiles. Drawing 5 or 8 bamboo completes a standard shape; a closed self-draw also supplies a yaku."}, {"After a winning draw", "123m456p234678s55p", "The 8 bamboo completes the 678 run. Keep all 14 tiles and announce tsumo rather than discarding again."}},
	3:  {{"A two-sided wait", "45s", "3 or 6 bamboo completes the run. Before visible copies are counted, that is up to eight tiles."}, {"An edge wait", "89p", "Only 7 dots completes the run. Ranks do not wrap from 9 back to 1."}},
	4:  {{"Keep five useful blocks", "123m456p23467s55p1z", "Keep 123m, 456p, 234s, 67s and 55p. The isolated East is the extra tile in this closed-hand teaching example."}, {"Do not break a complete run", "234m678p345s66z12p", "Three runs are already complete. The Green-dragon pair and 12p are the remaining blocks; the pair alone is not yakuhai."}},
	5:  {{"All simples", "234m456p234678s55p", "Every tile is a number 2–8, so tanyao is present. Opening this shape would preserve tanyao under the app's rules."}, {"A shape can have no yaku", "123m456p789s22255p", "On ron with 2 dots, without riichi or other bonuses, this closed hand has no yaku: it has a triplet, terminals, and no value set."}},
	6:  {{"A good riichi candidate", "123m456p23467s55p", "This closed tenpai waits on 5 or 8 bamboo. With enough points and live-wall tiles, riichi is available."}, {"Keep the new draw separate", "123m456p23467s55p1z", "After riichi, an unhelpful East draw normally has to be discarded. You cannot switch an older tile out to improve flexibility."}},
	7:  {{"Closed pinfu self-draw", "123m456p234678s55p", "South seat in East round, winning on 8s with riichi: riichi + menzen tsumo + pinfu = 3 han, 20 fu. Payments are 1,300 from East and 700 from each other player: 2,700 total."}, {"The same hand on ron", "123m456p234678s55p", "With riichi, won on 8s by ron as non-dealer: riichi + pinfu = 2 han, 30 fu, 2,000 points from the discarder."}},
	8:  {{"Safe against one player", "2p", "If the riichi player's discards include 2 dots, your 2 dots is genbutsu against that player. It is not automatically safe against the other two."}, {"A clear open-hand route", "777z", "An open Red-dragon set supplies one han of yakuhai. Decide what you will discard after pon and whether the remaining hand is fast enough."}},
	9:  {{"Seat and round are different", "111z222z", "As South in an East round, both East and South sets are valuable. A West set would not be a value set for you in this situation."}, {"Double wind", "111z", "As East in an East round, this set fills two roles: seat wind and round wind, for two han in total."}},
	10: {{"Choose a chi", "34m", "A 2m or 5m discard from the left player can form a run. The same discard from across the table cannot be called as chi."}, {"Choose a pon", "77z", "A Red-dragon discard from any opponent can complete a set. After opening, keep a path to four groups and a head."}},
	11: {{"The whole wait is blocked for ron", "123m456p23467s55p", "If 5s is in your own discards, both the 5s and 8s ron options are blocked. It is not just the discarded tile that becomes unusable for ron."}, {"Tsumo remains legal", "123m456p234678s55p", "Even with discard furiten, drawing the 8s yourself can win this closed hand. Menzen tsumo provides a yaku."}},
	12: {{"A concealed quad", "5555p", "Four 5 dots can be a concealed kan. It counts as one group, with a replacement draw; it is not four tiles toward two separate pairs."}, {"A kan is not free value", "1111m", "Even a terminal kan gives opponents a potential extra dora indicator. Consider their riichi and your own hand before declaring."}},
	13: {{"Tenpai", "123m456p23467s55p", "Three runs, a pair and 67s need one winning tile. This shape has shanten 0."}, {"One exchange to tenpai", "123m456p24s67s55p1z", "Two runs, a pair, two incomplete bamboo blocks and an isolated East make this 13-tile hand one-shanten. A useful draw can reach tenpai after a discard."}},
	14: {{"Two sides versus a gap", "45m46p", "45m accepts 3m and 6m; 46p accepts only 5p. Shape strength matters before you chase a specific yaku."}, {"Subtract visible copies", "45m333m66m", "If the three 3m and two 6m shown are already visible elsewhere, only one 3m and two 6m remain unseen for your 45m shape: three copies, not eight."}},
	15: {{"Two candidates for the head", "22m55p", "Drawing another 2m or 5p can make a set while leaving the other pair intact. There are only two unseen copies of each before other visible tiles are counted."}, {"A seven-pairs alternative", "11m22p33s445566z7z", "Six distinct pairs plus a singleton can form seven-pairs tenpai. Do not automatically break pairs just to force a standard hand."}},
	16: {{"A stretched single wait", "2345m", "2m makes 22m + 345m; 5m makes 234m + 55m. These are pair completions, so this block does not qualify as a pinfu two-sided winning wait."}, {"Three-way run wait", "34567s", "2s makes 234s + 567s, 5s makes 345s + 567s, and 8s makes 345s + 678s. Find every decomposition."}},
	17: {{"A redundant connection", "5578m2455p133s777z", "Divide into 55m / 78m / 2455p / 133s / 777z. Inside the dots block, 45 already accepts 3p, so 2p can be removed without losing that draw."}, {"Shape before isolated honors", "234m456p34567s88p4z", "North is outside the five useful blocks here. Removing it leaves three complete runs, 67s and the head 88p."}},
	18: {{"Pinfu succeeds", "123m456p234678s55p", "Closed, won on 8s: four runs, a number pair, and the 67s two-sided wait meet all pinfu requirements."}, {"A dragon pair stops pinfu", "123m456p234678s77z", "Even with four runs and a two-sided winning tile, the Red-dragon pair is a value pair. The hand is not pinfu."}},
	19: {{"One dragon set", "123m456p789s777z55p", "Red dragons provide one han, even when that set was called. The other three groups and pair still have to be complete."}, {"A pair is not a value set", "77z", "Two Red dragons are a pair, not yakuhai. A third can complete the yaku, but do not assume it will arrive."}},
	20: {{"Number indicators", "9m4p", "The 9m indicator points to 1m; the 4p indicator points to 5p. Those indicators do not themselves earn the bonus."}, {"Honor cycles", "47z", "North points back to East. Red points back to White. Wind and dragon cycles are separate."}},
	21: {{"Seven distinct pairs", "1122m3344p5566s77z", "Seven pairs is a closed two-han yaku with exactly 25 fu. Each pair must be a different tile type."}, {"A half-flush route", "123456789m11155z", "One numbered suit plus honors gives honitsu: three han closed, two open. This hand also has an East set, valuable in an East round."}},
	22: {{"Pinfu has exact shortcuts", "123m456p234678s55p", "Won on 8s: pinfu tsumo uses 20 fu; pinfu ron uses 30 fu. The win type changes the calculation even with the same tiles."}, {"Seven pairs never rounds to 30", "1122m3344p5566s77z", "Seven pairs is exactly 25 fu. At two han, non-dealer ron is 1,600, not the 2,000 of a 30-fu two-han hand."}},
	23: {{"Attack with a reason", "123m456p23467s55p", "Early closed tenpai with a two-sided wait and no active threat is a sensible riichi candidate. Consider your points and the live wall too."}, {"Dama still needs a yaku", "123m456p789s22255p", "Ron on 2p without riichi supplies no yaku in this example. Keeping a yaku-less hand quiet does not make ron legal."}},
	24: {{"Genbutsu beats a guess", "4p", "If the riichi player already discarded 4p, it is safe from their ron because of furiten. That is stronger information than a suji inference."}, {"Suji does not cover every wait", "11p77p", "After that player discards 4p, a remaining 1p or 7p can still complete a set wait. Suji cannot rule these out."}},
	25: {{"Pon with a yaku route", "77z234m456p134s55p", "If Red is discarded, pon secures yakuhai. Before calling, decide the next discard and compare the resulting readiness with staying closed."}, {"Closed value can be lost", "123m123p123s456s55p", "This closed sanshoku shape is worth two han from sanshoku; opening a run would reduce that yaku to one han and remove riichi eligibility."}},
	26: {{"A distant, cheap hand", "1239m4567p2466s1z", "Against a late riichi, a slow hand without clear value usually calls for folding. Choose a genbutsu tile when available rather than the most efficient dangerous discard."}, {"A stronger attacking case", "234m456p23467s55p", "Closed tenpai with tanyao and a two-sided wait is a more credible push than a cheap distant hand, but wait quality, value, turn and safe alternatives still matter."}},
	27: {{"A small win can be enough", "234m456p234678s55p", "You trail second place by 1,500. As a non-dealer, ron on 8s from fourth place with this closed hand gives tanyao + pinfu: 2 han, 30 fu, 2,000 points. With no honba or deposits, you move 500 ahead of second place."}, {"Deposits are not han", "123m456p234678s55p", "A 2,000-point ron with one honba costs the discarder 2,300. A one-stick riichi pot gives the winner another 1,000 from the pot. Neither adds han or changes fu."}},
}

var extraChecks = map[int]checkQuestion{
	0:  {"Can East, South and West form a run?", []string{"Yes, in wind order", "No, honors do not form runs", "Only during East round"}, 1, "Honors only form sets, pairs or kans of identical tiles; wind order does not make a run."},
	1:  {"A 14-tile shape is complete. Is that alone enough to win?", []string{"Yes", "No, it also needs a yaku and legal win conditions", "Only with a dragon pair"}, 1, "Shape, yaku, and legal win conditions are separate checks. A shape alone is not a legal win."},
	2:  {"Another player discards your legal winning tile. What call wins it?", []string{"Tsumo", "Ron", "Chi"}, 1, "Ron wins on an opponent's discard. Tsumo wins on your own draw; chi only calls a run."},
	3:  {"How many tile types finish a 4–6 gap as a run?", []string{"One", "Two", "Three"}, 0, "Only 5 fills 4–6. This gap wait has up to four available copies before visible tiles are counted."},
	4:  {"When applying five blocks, what are you looking for?", []string{"Five finished runs", "Four future groups and a head", "Five pairs"}, 1, "Blocks include incomplete candidates. The goal is four groups plus one pair, not five groups."},
	5:  {"Does an open set of White dragons provide yakuhai?", []string{"Yes", "Only with self-draw", "No"}, 0, "Dragon sets are one-han yakuhai open or closed. A pair is insufficient."},
	6:  {"After riichi, you draw an unhelpful tile. What normally happens?", []string{"Keep it and discard any old tile", "Discard the new draw", "Take the deposit back"}, 1, "Riichi locks the hand. Normally you discard the new draw unless it wins; special kan rules are more restrictive."},
	7:  {"A non-dealer mangan tsumo has no honba. What are the payments?", []string{"2,000 from everyone", "4,000 from East and 2,000 from each other player", "8,000 from each opponent"}, 1, "East pays double the other two players: 4,000 + 2,000 + 2,000 = 8,000."},
	8:  {"A tile is genbutsu against one riichi player. Is it safe against everyone?", []string{"Yes", "No", "Only in the East round"}, 1, "Genbutsu is specific to that opponent. Check the other players separately."},
	9:  {"You are East in an East round. How many han does an East set provide?", []string{"One", "Two", "Three"}, 1, "The set satisfies both seat-wind and round-wind yakuhai, one han for each role."},
	10: {"Can you call pon using a discard from the player across the table?", []string{"Yes", "No", "Only with a dragon"}, 0, "Pon can use any opponent's discard. Chi is the call restricted to the left player."},
	11: {"While in discard furiten, can a legal self-draw still win?", []string{"Yes", "No", "Only if you pay 1,000"}, 0, "Furiten blocks ron. Tsumo remains possible when the hand otherwise qualifies."},
	12: {"Why can kan be dangerous against an opponent's riichi?", []string{"It removes their yaku", "It can reveal extra dora that increase their hand value", "It guarantees they fold"}, 1, "Extra dora may benefit opponents, and a riichi winner can also benefit from additional ura indicators."},
	13: {"What does shanten −1 describe?", []string{"A complete shape", "Tenpai", "A hand with no yaku"}, 0, "Minus one is a complete shape. It does not by itself prove that a ron is legal."},
	14: {"45m waits on 3m or 6m. Three 3m and two 6m are already visible. How many copies remain unseen?", []string{"Three", "Five", "Eight"}, 0, "Only one of the four 3m and two of the four 6m remain unseen: three copies in total."},
	15: {"With four or more pairs, which alternative should you compare?", []string{"Seven pairs", "Open riichi", "Five runs"}, 0, "Seven pairs may be competitive with a standard hand. Compare readiness and useful draws, rather than forcing either route."},
	16: {"A 3–4–5–6–7 bamboo block needs one tile to become two runs. What completes it?", []string{"Only 5 bamboo", "2, 5 or 8 bamboo", "3 or 7 bamboo"}, 1, "2 gives 234+567, 5 gives 345+567, and 8 gives 345+678."},
	17: {"Two discards leave the same shanten. What is a useful next comparison?", []string{"Useful draw counts, then value and safety", "Always discard the highest rank", "Always break the pair"}, 0, "Ukeire helps compare speed at equal shanten. Hand value and defense can justify a different choice."},
	18: {"Can a pair of Green dragons be the head of pinfu?", []string{"Yes", "No", "Only on tsumo"}, 1, "Any dragon pair is a value pair and prevents pinfu, even though that pair alone is not yakuhai."},
	19: {"As South in an East round, does a West set count as wind yakuhai?", []string{"Yes", "No", "Only if open"}, 1, "West is neither your seat nor the round wind in this situation. The hand may have some other yaku, but not West yakuhai."},
	20: {"A North indicator points to which dora?", []string{"East", "White dragon", "North"}, 0, "The wind cycle is East → South → West → North → East. Dragon indicators use a separate cycle."},
	21: {"How does opening affect honitsu?", []string{"It becomes illegal", "It drops from 3 han to 2", "Its value is unchanged"}, 1, "Honitsu is 3 han closed and 2 open. Opening can trade hand value for speed."},
	22: {"A seven-pairs hand has 25 fu. Do you round that to 30?", []string{"Yes", "No", "Only on ron"}, 1, "Seven pairs is the fixed 25-fu exception, on both ron and tsumo."},
	23: {"Why might you stay in dama with an already valuable legal hand?", []string{"To keep flexibility or meet a placement goal", "Because dama adds two han", "Because riichi is always illegal at tenpai"}, 0, "Dama can preserve flexibility and make a sufficient win less conspicuous. It does not add a yaku or han."},
	24: {"Which evidence is stronger against one opponent's ron?", []string{"Their own discard of that tile (genbutsu)", "A suji inference", "The tile looks old"}, 0, "Their own discard invokes furiten. Suji only reduces some specific two-sided-wait possibilities."},
	25: {"A call leaves a cheap, distant hand without a clear yaku. What should you usually do?", []string{"Call anyway", "Pass and preserve flexibility", "Declare riichi after calling"}, 1, "Opening without speed, value or a yaku route often gives away flexibility for little benefit."},
	26: {"When deciding whether to push, which set of factors matters most?", []string{"Readiness, value, wait, turn and threats", "Only the number of dora", "Only the newest tile"}, 0, "Push/fold is a risk-and-reward decision. No single tile feature replaces the table context."},
	27: {"Do honba or collected riichi deposits add han to your hand?", []string{"Yes", "No", "Only for the dealer"}, 1, "They change the points exchanged separately. They do not change the hand's han or fu."},
}

func lessonChecks(i int) []checkQuestion {
	l := lessons[i]
	return []checkQuestion{{l.question, l.choices, l.correct, l.explanation}, extraChecks[i]}
}
func lessonKey(i, q int) string { return fmt.Sprintf("lesson:%d:%d", i, q) }
func stageForLesson(i int) int {
	for s, stage := range courseStages {
		for _, v := range stage.lessons {
			if i == v {
				return s
			}
		}
	}
	return 0
}
func courseOrder() []int {
	var out []int
	for _, stage := range courseStages {
		out = append(out, stage.lessons...)
	}
	return out
}
